const d = msg.payload;
const rec = {suhu:Number(d.suhu), kelembaban:Number(d.kelembaban), received:new Date().toISOString()};
flow.set("latest", rec);
let th = global.get("threshold"); if (th === undefined || th === null) th = 30;

const toDb = {params:{$suhu:rec.suhu, $hum:rec.kelembaban, $received:rec.received}};
const toWs = {payload:{type:"sensor", suhu:rec.suhu, kelembaban:rec.kelembaban, received:rec.received, threshold:th}};
let alert = null;
if (rec.suhu > th && Date.now() - (flow.get("lastAlert")||0) > 30000) {   // cooldown 30 dtk
  flow.set("lastAlert", Date.now());
  alert = {payload:{type:"alert", message:`Suhu ${rec.suhu}°C melewati batas ${th}°C`, suhu:rec.suhu, threshold:th, received:rec.received}};
}
return [toDb, toWs, alert];

const H = {"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"Content-Type, X-API-Key","Access-Control-Allow-Methods":"GET, POST, PUT, OPTIONS"};
const KEY = env.get("API_KEY") || "iot-secret-123";
msg.headers = H;
const authed = msg.req.headers["x-api-key"] === KEY;
if (!authed) { msg.statusCode = 401; msg.payload = {status:"error", message:"Unauthorized: header X-API-Key salah atau tidak ada"}; }
if (!authed) return msg;
const l = flow.get("latest");
msg.statusCode = 200;
msg.payload = {status:"success", data: l ? {suhu:l.suhu, kelembaban:l.kelembaban, received:l.received} : {suhu:null, kelembaban:null}};
return msg;

const H = {"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"Content-Type, X-API-Key","Access-Control-Allow-Methods":"GET, POST, PUT, OPTIONS"};
const KEY = env.get("API_KEY") || "iot-secret-123";
msg.headers = H;
const authed = msg.req.headers["x-api-key"] === KEY;
if (!authed) { msg.statusCode = 401; msg.payload = {status:"error", message:"Unauthorized: header X-API-Key salah atau tidak ada"}; }
if (!authed) return [null, msg];
const n = Math.min(Math.max(parseInt(msg.req.query.n) || 50, 1), 500);
msg.params = {$n:n};
return [msg, null];

msg.headers = {"Access-Control-Allow-Origin":"*"};
msg.statusCode = 200;
msg.payload = {status:"success", data: msg.payload.reverse()};   // urut lama -> baru
return msg;

const H = {"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"Content-Type, X-API-Key","Access-Control-Allow-Methods":"GET, POST, PUT, OPTIONS"};
const KEY = env.get("API_KEY") || "iot-secret-123";
msg.headers = H;
const authed = msg.req.headers["x-api-key"] === KEY;
if (!authed) { msg.statusCode = 401; msg.payload = {status:"error", message:"Unauthorized: header X-API-Key salah atau tidak ada"}; }
if (!authed) return [msg, null];
const b = msg.payload || {};
if (b.device !== "lamp" || !["on","off"].includes(b.action)) {
  msg.statusCode = 400;
  msg.payload = {status:"error", message:"device harus 'lamp' dan action 'on'/'off'"};
  return [msg, null];
}
msg.statusCode = 200;
const out = {payload:{device:b.device, action:b.action}};
msg.payload = {status:"success", message:`${b.device} -> ${b.action}`};
return [msg, out];

const H = {"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"Content-Type, X-API-Key","Access-Control-Allow-Methods":"GET, POST, PUT, OPTIONS"};
const KEY = env.get("API_KEY") || "iot-secret-123";
msg.headers = H;
const authed = msg.req.headers["x-api-key"] === KEY;
if (!authed) { msg.statusCode = 401; msg.payload = {status:"error", message:"Unauthorized: header X-API-Key salah atau tidak ada"}; }
if (!authed) return [msg, null];
let th = global.get("threshold"); if (th === undefined || th === null) th = 30;
if (msg.req.method === "PUT") {
  const raw = msg.payload ? msg.payload.threshold : undefined;
  const v = Number(raw);
  if (raw === undefined || raw === null || raw === "" || !Number.isFinite(v)) {
    msg.statusCode = 400;
    msg.payload = {status:"error", message:"threshold harus berupa angka"};
    return [msg, null];
  }
  global.set("threshold", v);
  flow.set("lastAlert", 0);
  msg.statusCode = 200;
  msg.payload = {status:"success", data:{threshold:v}};
  return [msg, {payload:{type:"threshold", threshold:v}}];
}
msg.statusCode = 200;
msg.payload = {status:"success", data:{threshold:th}};
return [msg, null];
